namespace {

std::string read_text(const char *path) {
  std::ifstream input(path);
  if (!input) {
    throw std::runtime_error("input file could not be opened");
  }
  std::ostringstream buffer;
  buffer << input.rdbuf();
  return buffer.str();
}

}  // namespace

int main(int argc, char **argv) {
  if (argc != 2) {
    std::cerr << "usage: task105_probe <molfile>\n";
    return 2;
  }

  const auto molblock = read_text(argv[1]);
  std::unique_ptr<RDKit::RWMol> mol(RDKit::MolBlockToMol(molblock));
  if (!mol) {
    std::cerr << "load=failed\n";
    return 3;
  }

  RDKit::MolStandardize::TautomerEnumerator enumerator;
  enumerator.setRemoveBondStereo(false);

  std::unique_ptr<RDKit::ROMol> canonical(enumerator.canonicalize(*mol));
  const auto serial = RDKit::MolToSmiles(*canonical);
  if (serial.empty()) {
    return 4;
  }

  std::cout << "workflow_complete\n";
  return 0;
}

