  // bonds, and in case of ties, start with the bond that has
  // the lowest position in the molStack

  auto getNeighboringStereoBond = [&mol](const Atom *dblBndAtom,
                                         const Bond *nbrBnd) -> Bond * {
    auto otherAtom = nbrBnd->getOtherAtom(dblBndAtom);
    for (const auto bond : mol.atomBonds(otherAtom)) {
      if (bond != nbrBnd && bond->getBondType() == Bond::DOUBLE &&
          bond->getStereo() > Bond::STEREOANY) {
        return bond;
      }
    }
    return nullptr;
  };

  std::greater<const unsigned int &> molStackComparer;
  std::less<const unsigned int &> numStereoNbrsComparer;

  std::unordered_map<const Bond *, std::vector<Bond *>> stereoBondNbrs;
  auto compareBondPriority = [&stereoBondNbrs, &bondVisitOrders,
                              &molStackComparer, &numStereoNbrsComparer](
                                 const Bond *aBnd, const Bond *bBnd) {
    const auto aNumStereoNbrs = stereoBondNbrs[aBnd].size();
    const auto bNumStereoNbrs = stereoBondNbrs[bBnd].size();

    if (aNumStereoNbrs == bNumStereoNbrs) {
      return molStackComparer(bondVisitOrders[aBnd->getIdx()],
                              bondVisitOrders[bBnd->getIdx()]);
    }
    return numStereoNbrsComparer(aNumStereoNbrs, bNumStereoNbrs);
  };

  std::priority_queue<Bond *, std::vector<Bond *>,
                      decltype(compareBondPriority)>
      q{compareBondPriority};

  for (auto &msI : molStack) {
    if (msI.type != MOL_STACK_BOND) {
      // not a bond, skip it
      continue;
    }

    auto bond = msI.obj.bond;
    Bond::BondDir dir = bond->getBondDir();
    if (dir == Bond::ENDDOWNRIGHT || dir == Bond::ENDUPRIGHT) {
      bond->setBondDir(Bond::NONE);
    }

    if (bond->getBondType() != Bond::DOUBLE ||
        bond->getStereo() <= Bond::STEREOANY ||
        bond->getStereoAtoms().size() < 2) {
      // not a bond that can have stereo or that needs canonicalization
      bond->setStereo(Bond::STEREONONE);
      continue;
    }

    auto &currentNbrs = stereoBondNbrs[bond];
    for (const auto *dblBondAtom : {bond->getBeginAtom(), bond->getEndAtom()}) {
      for (const auto *nbrBond : mol.atomBonds(dblBondAtom)) {
        if (!canHaveDirection(*nbrBond)) {
          continue;
        }
        auto nbrDblBnd = getNeighboringStereoBond(dblBondAtom, nbrBond);
        if (nbrDblBnd != nullptr) {
          currentNbrs.push_back(nbrDblBnd);
        }
      }
    }
    std::ranges::sort(currentNbrs, [&molStackComparer, &bondVisitOrders](
                                       const Bond *aBnd, const Bond *bBnd) {
      // Reversing the bonds is intentional: molStackComparer
      // is a std::greater comparer (priority queue returns
      // the highest element), but here we want to sort in
      // increasing order, so we want a std::less comparer,
      // which can be achieved by reversing the std::greater
      // because we can have no ties here
      return molStackComparer(bondVisitOrders[bBnd->getIdx()],
                              bondVisitOrders[aBnd->getIdx()]);
    });

    q.emplace(bond);
  }

  // Now that we have bonds in the order we want to handle them,
  // do the canonicalization
  std::vector<bool> seen_bonds(mol.getNumBonds());

  unsigned int factor = 100;
  while (factor < mol.getNumAtoms()) {
    factor *= 10;
  }

#ifdef VERBOSE_CANON
  BOOST_LOG(rdDebugLog) << "rerank PRE: " << std::endl;
  for (int i = 0; i < mol.getNumAtoms(); i++) {
    BOOST_LOG(rdDebugLog) << "  " << i << ": " << ranks[i] << std::endl;
  }
#endif

  DOUBLE_VECT invars(mol.getNumAtoms());
  // and now supplement them:
  for (unsigned int i = 0; i < mol.getNumAtoms(); ++i) {
    invars[i] = ranks[i] * factor;
    const Atom *atom = mol.getAtomWithIdx(i);
    // Priority order: R > S > nothing
    std::string cipCode;
    if (atom->getPropIfPresent(common_properties::_CIPCode, cipCode)) {
      if (cipCode == "S") {
        invars[i] += 10;
      } else if (cipCode == "R") {
        invars[i] += 20;
      }
    }
    for (const auto oBond : mol.atomBonds(atom)) {
      if (oBond->getBondType() == Bond::DOUBLE) {
        if (oBond->getStereo() == Bond::STEREOE) {
          invars[i] += 1;
        } else if (oBond->getStereo() == Bond::STEREOZ) {
          invars[i] += 2;
        }
      }
    }
  }
  iterateCIPRanks(mol, invars, ranks, true);
  // copy the ranks onto the atoms:
  for (unsigned int i = 0; i < mol.getNumAtoms(); i++) {
    mol.getAtomWithIdx(i)->setProp(common_properties::_CIPRank, ranks[i]);
  }

#ifdef VERBOSE_CANON
  BOOST_LOG(rdDebugLog) << "   post: " << std::endl;
  for (int i = 0; i < mol.getNumAtoms(); i++) {
    BOOST_LOG(rdDebugLog) << "  " << i << ": " << ranks[i] << std::endl;
  }
#endif
}

bool hasStereoBondDir(const Bond *bond) {
  PRECONDITION(bond, "no bond");
  return bond->getBondDir() == Bond::BondDir::ENDDOWNRIGHT ||
         bond->getBondDir() == Bond::BondDir::ENDUPRIGHT;
}

const Bond *getNeighboringDirectedBond(const ROMol &mol, const Atom *atom) {
  PRECONDITION(atom, "no atom");
  for (const auto &bondIdx :
       boost::make_iterator_range(mol.getAtomBonds(atom))) {
    const Bond *bond = mol[bondIdx];

    if (bond->getBondType() != Bond::BondType::DOUBLE &&
        hasStereoBondDir(bond)) {
      return bond;
    }
  }
  return nullptr;
}

Bond::BondStereo translateEZLabelToCisTrans(Bond::BondStereo label) {
  switch (label) {
    case Bond::STEREOE:
      return Bond::STEREOTRANS;
    case Bond::STEREOZ:
      return Bond::STEREOCIS;
    default:
      return label;
  }
}

INT_VECT findStereoAtoms(const Bond *bond) {
  PRECONDITION(bond, "bad bond");
  PRECONDITION(bond->hasOwningMol(), "no mol");
  PRECONDITION(bond->getBondType() == Bond::DOUBLE, "not double bond");
  PRECONDITION(bond->getStereo() > Bond::BondStereo::STEREOANY,
               "no defined stereo");

  if (!bond->getStereoAtoms().empty()) {
    return bond->getStereoAtoms();
  }
  if (bond->getStereo() == Bond::BondStereo::STEREOE ||
      bond->getStereo() == Bond::BondStereo::STEREOZ) {
    const Atom *startStereoAtom =
        findHighestCIPNeighbor(bond->getBeginAtom(), bond->getEndAtom());
    const Atom *endStereoAtom =
        findHighestCIPNeighbor(bond->getEndAtom(), bond->getBeginAtom());

    if (startStereoAtom == nullptr || endStereoAtom == nullptr) {
      return {};
    }

    int startStereoAtomIdx = static_cast<int>(startStereoAtom->getIdx());
    int endStereoAtomIdx = static_cast<int>(endStereoAtom->getIdx());

    return {startStereoAtomIdx, endStereoAtomIdx};
  } else {
    BOOST_LOG(rdWarningLog) << "Unable to assign stereo atoms for bond "
                            << bond->getIdx() << std::endl;
    return {};
  }
}
